1319	# Parses Codex's last message in structured mode. Tolerates a ```json fence around
1320	# the object. Never throws: any failure becomes a validation error. Outcomes
1321	# (amendment M2 + review F04-4/5/6):
1322	#   Valid=$false             not JSON, any structural error, or a failure while
1323	#                            normalizing: ValidationError = the first error, no
1324	#                            verdict, the caller records no findings
1325	#   Valid, VerdictInvalid    structurally valid but the verdict does not fit the
1326	#                            purpose or contradicts new / still-open prior blockers:
1327	#                            findings are ingested, Verdict '', ValidationError and
1328	#                            VerdictProblem say why
1329	#   Valid                    Verdict = the reply's verdict
1330	# UncheckedPriorBlockers lists open prior blockers an ACCEPT left not-checked.
1331	# $PriorFindings: { id; severity; status } of the open prior findings listed in the
1332	# prompt.
1333	function ConvertFrom-StructuredReply {
1334	    param([string]$Text, [string]$Purpose = '', $PriorFindings = @())
1335	    $result = [pscustomobject]@{
1336	        Valid                  = $false
1337	        Reply                  = $null
1338	        Errors                 = [string[]]@()
1339	        ValidationError        = ''
1340	        Verdict                = ''
1341	        VerdictInvalid         = $false
1342	        VerdictProblem         = ''
1343	        UncheckedPriorBlockers = [string[]]@()
1344	        BlockerCount           = 0
1345	        Fenced                 = $false
1346	    }
1347	    $t = ''
1348	    if ($Text) { $t = $Text.Trim() }
1349	    if (-not $t) {
1350	        $result.ValidationError = 'empty reply'
1351	        $result.Errors = [string[]]@('empty reply')
1352	        return $result
1353	    }
1354	    $fence = [regex]::Match($t, '^```[A-Za-z0-9_-]*[ \t]*\r?\n(?<body>[\s\S]*?)\r?\n[ \t]*```$')
1355	    if ($fence.Success) { $t = $fence.Groups['body'].Value.Trim(); $result.Fenced = $true }
1356	    $obj = $null
1357	    try {
1358	        $obj = ConvertFrom-Json -InputObject $t
1359	    } catch {
1360	        $msg = ConvertTo-OneLine $_.Exception.Message
1361	        if ($msg.Length -gt 120) { $msg = $msg.Substring(0, 120) + '...' }
1362	        $result.ValidationError = "not valid JSON: $msg"
1363	        $result.Errors = [string[]]@($result.ValidationError)
1364	        return $result
1365	    }
1366	    try {
