1368	        if ($errs.Count -gt 0) {
1369	            $result.Errors = $errs
1370	            $result.ValidationError = $errs[0]
1371	            return $result
1372	        }
1373	        $norm = ConvertTo-NormalizedReply -Reply $obj
1374	        $sem = Test-ReplySemantics -Reply $norm -Purpose $Purpose -PriorFindings $PriorFindings
1375	    } catch {
1376	        $msg = ConvertTo-OneLine $_.Exception.Message
1377	        if ($msg.Length -gt 160) { $msg = $msg.Substring(0, 160) + '...' }
1378	        $result.ValidationError = "could not validate the reply: $msg"
1379	        $result.Errors = [string[]]@($result.ValidationError)
1380	        return $result
1381	    }
1382	    $result.Valid = $true
1383	    $result.Reply = $norm
